from fractions import Fraction
from sympy import symbols, expand

x = symbols("x")


def solve(kind, nums):
    print(f"{kind} {nums}")
    if kind == "evaluate":
        a, b, c, v = nums[0], nums[1], nums[2], Fraction(nums[3], nums[4])
        print(f"  {a}({v})^2 + ({b})({v}) + {c} = {a * v * v} + ({b * v}) + {c} = {a * v * v + b * v + c}")
    elif kind == "expand":
        p, q, r, s = nums[0], nums[1], nums[2], nums[3]
        print(f"  first {p * r}, outer {p * s}, inner {q * r}, last {q * s}: {expand((p*x + q)*(r*x + s))}")
    elif kind == "linear":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        coef, right = a - c, d - b
        print(f"  subtract {c}x and {b}: {coef}x = {right}")
        if coef != 0:
            print(f"  x = {Fraction(right, coef)}")
        elif right == 0:
            print("  0 = 0: every number is a solution")
        else:
            print(f"  0 = {right}: no solution")
    elif kind == "less":
        a, b, c, d = nums[0], nums[1], nums[2], nums[3]
        k, m = a - c, d - b
        print(f"  collect: {k}x < {m}")
        if k > 0:
            print(f"  divide by {k}, keep the sign: x < {Fraction(m, k)}")
        elif k < 0:
            print(f"  divide by {k}, a negative, flip: x > {Fraction(m, k)}")
        elif 0 < m:
            print(f"  0 < {m} is true: all real numbers")
        else:
            print(f"  0 < {m} is false: no solution")
    elif kind == "absolute":
        p, a, b, q, s = nums[0], nums[1], nums[2], nums[3], nums[4]
        r = Fraction(s - q, p)
        print(f"  isolate: |inside| = {r}")
        if r < 0:
            print("  never negative: no solution")
        elif r == 0:
            print(f"  inside = 0: x = {Fraction(-b, a)}")
        else:
            x1, x2 = Fraction(r - b, a), Fraction(-r - b, a)
            if x2 < x1:
                x1, x2 = x2, x1
            print(f"  inside = {r} or {-r}: x = {x1} or x = {x2}")
    elif kind == "system":
        a, b, e, c, d, f = nums[0], nums[1], nums[2], nums[3], nums[4], nums[5]
        det = a * d - b * c
        print(f"  eliminate: {det}x = {e * d - b * f} and {det}y = {a * f - c * e}")
        print(f"  x = {Fraction(e * d - b * f, det)}, y = {Fraction(a * f - c * e, det)}")


solve("evaluate", [2, -3, 4, -2, 1])
solve("expand", [1, 4, 1, -6])
solve("linear", [6, 5, 2, -11])
solve("linear", [3, 6, 3, 5])
solve("less", [-3, 5, 0, 14])
solve("less", [2, 1, 2, 4])
solve("absolute", [1, 1, -4, 0, 7])
solve("absolute", [1, 1, 6, 0, -2])
solve("system", [1, 1, 12, 1, -1, 2])

