from fractions import Fraction
from sympy import symbols, expand

x = symbols("x")
count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "evaluate":
        a, b, c, v = nums[0], nums[1], nums[2], Fraction(nums[3], nums[4])
        print(f"  value {a * v * v + b * v + c}")
    elif kind == "expand":
        p, q, r, s = nums[0], nums[1], nums[2], nums[3]
        print(f"  {expand((p*x + q)*(r*x + s))}")
    elif kind == "linear":
        coef, right = nums[0] - nums[2], nums[3] - nums[1]
        if coef != 0:
            print(f"  x = {Fraction(right, coef)}")
        elif right == 0:
            print("  every number")
        else:
            print("  no solution")
    elif kind == "less":
        k, m = nums[0] - nums[2], nums[3] - nums[1]
        if k > 0:
            print(f"  x < {Fraction(m, k)}")
        elif k < 0:
            print(f"  x > {Fraction(m, k)}")
        elif 0 < m:
            print("  all real numbers")
        else:
            print("  no solution")
    elif kind == "absolute":
        p, a, b, q, s = nums[0], nums[1], nums[2], nums[3], nums[4]
        r = Fraction(s - q, p)
        if r < 0:
            print("  no solution")
        elif r == 0:
            print(f"  x = {Fraction(-b, a)}")
        else:
            x1, x2 = Fraction(r - b, a), Fraction(-r - b, a)
            if x2 < x1:
                x1, x2 = x2, x1
            print(f"  x = {x1} or x = {x2}")
    elif kind == "system":
        a, b, e, c, d, f = nums[0], nums[1], nums[2], nums[3], nums[4], nums[5]
        det = a * d - b * c
        print(f"  x = {Fraction(e * d - b * f, det)}, y = {Fraction(a * f - c * e, det)}")

import math
from fractions import Fraction

count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "distribute":
        p, q, r, s = nums[0], nums[1], nums[2], nums[3]
        coef, right = p - r, s - p * q
        if coef != 0:
            print(f"  x = {Fraction(right, coef)}")
        elif right == 0:
            print("  every number")
        else:
            print("  no solution")
    elif kind == "clear":
        p, q, r = nums[0], nums[1], nums[2]
        L = math.lcm(p, q)
        coef = L // p + L // q
        if coef != 0:
            print(f"  x = {Fraction(L * r, coef)}")
        elif r == 0:
            print("  every number")
        else:
            print("  no solution")
    elif kind == "within":
        a, b, r = nums[0], nums[1], nums[2]
        if r < 0:
            print("  no solution")
        else:
            lo, hi = Fraction(-r - b, a), Fraction(r - b, a)
            if lo > hi:
                lo, hi = hi, lo
            print(f"  [{lo}, {hi}]")
    elif kind == "substitute":
        m, kk, a, b, c = nums[0], nums[1], nums[2], nums[3], nums[4]
        x0 = Fraction(c - b * kk, a + b * m)
        print(f"  x = {x0}, y = {m * x0 + kk}")
    elif kind == "plans":
        f1, r1, f2, r2 = nums[0], nums[1], nums[2], nums[3]
        g = Fraction(f2 - f1, r1 - r2)
        if r1 > r2:
            print(f"  equal at {g}, plan 1 cheaper below")
        else:
            print(f"  equal at {g}, plan 1 cheaper above")

from fractions import Fraction

count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "consecutive":
        kk, step, total = nums[0], nums[1], nums[2]
        offset = step * kk * (kk - 1) // 2
        if (total - offset) % kk == 0:
            n = (total - offset) // kk
            found = []
            for j in range(kk):
                found.append(n + step * j)
            print(f"  {found}")
        else:
            print("  no such integers")
    elif kind == "travel":
        print(f"  t = {Fraction(nums[2], nums[0] + nums[1])} hours")
    elif kind == "mixture":
        p1, v1 = Fraction(nums[0], 100), nums[1]
        p2, target = Fraction(nums[2], 100), Fraction(nums[3], 100)
        x = (target * v1 - p1 * v1) / (p2 - target)
        if x < 0:
            print("  out of reach")
        else:
            print(f"  add {x} L")
    elif kind == "together":
        rate = Fraction(1, nums[0]) + Fraction(1, nums[1])
        if rate <= 0:
            print("  never finishes")
        else:
            print(f"  {1 / rate} hours")
    elif kind == "budget":
        print(f"  h <= {Fraction(nums[2] - nums[0], nums[1])}")
    elif kind == "tickets":
        total, p1, p2, money = nums[0], nums[1], nums[2], nums[3]
        a = Fraction(money - p2 * total, p1 - p2)
        print(f"  a = {a}, c = {total - a}")

from fractions import Fraction
from sympy import symbols, expand

x = symbols("x")
count = int(input())
for i in range(count):
    kind = input()
    k = int(input())
    nums = []
    for j in range(k):
        nums.append(int(input()))
    print(f"Problem {i + 1}: {kind} {nums}")
    if kind == "outside":
        a, b, r = nums[0], nums[1], nums[2]
        if r < 0:
            print("  all real numbers")
        else:
            lo, hi = Fraction(-r - b, a), Fraction(r - b, a)
            if lo > hi:
                lo, hi = hi, lo
            print(f"  (-inf, {lo}) U ({hi}, inf)")
    elif kind == "classify":
        a, b, e, c, d, f = nums[0], nums[1], nums[2], nums[3], nums[4], nums[5]
        det = a * d - b * c
        if det != 0:
            print(f"  x = {Fraction(e * d - b * f, det)}, y = {Fraction(a * f - c * e, det)}")
        elif e * d - b * f == 0 and a * f - c * e == 0:
            print("  infinitely many")
        else:
            print("  no solution")
    elif kind == "refute":
        diff = expand((x + nums[0])**2 - (x**2 + nums[1]))
        print(f"  difference {diff}, equivalent {diff == 0}")
    elif kind == "rate":
        P, A, t = nums[0], nums[1], nums[2]
        r = Fraction(A - P, P * t)
        print(f"  r = {r} = {float(r * 100):.2f}%")
